    clearInterval(timerId);
    timerId = null;
    els.startBtn.textContent = '"'Start';
    render();
  }

  function reset() {
    stop();
    startPhase(mode);
  }

  function onTab(e) {
    var m = e.currentTarget.dataset.mode;
    if (m === mode) return;
    stop();
    startPhase(m);
  }

